import { firebaseConfig, recaptchaEnterpriseSiteKey, functionsRegion, waitlistBackendReady } from './firebase-config.js';
const $=s=>document.querySelector(s);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const button=(t,h='waitlist',cls='')=>`<a class="button ${cls}" href="#${h}">${t}</a>`;
let submitWaitlist = null, connectError = false;
const NOTICE_VERSION = 'prelaunch-v2';
async function connectFirebase() {
  if (!firebaseConfig || !recaptchaEnterpriseSiteKey || !waitlistBackendReady) return;
  try {
    const [{ initializeApp }, { initializeAppCheck, ReCaptchaEnterpriseProvider, getToken }, { getFunctions, httpsCallable }] = await Promise.all([
      import('https://www.gstatic.com/firebasejs/12.0.0/firebase-app.js'),
      import('https://www.gstatic.com/firebasejs/12.0.0/firebase-app-check.js'),
      import('https://www.gstatic.com/firebasejs/12.0.0/firebase-functions.js'),
    ]);
    const app = initializeApp(firebaseConfig);
    const appCheck = initializeAppCheck(app, {
      provider: new ReCaptchaEnterpriseProvider(recaptchaEnterpriseSiteKey),
      isTokenAutoRefreshEnabled: true,
    });
    const call = httpsCallable(getFunctions(app, functionsRegion), 'joinFynxWalletWaitlist', { timeout: 40000 });
    submitWaitlist = async data => {
      await getToken(appCheck);
      return (await call(data)).data;
    };
  } catch {
    connectError = true;
  }
  render();
}
async function handleWaitlistSubmit(event) {
  event.preventDefault();
  const form = event.currentTarget;
  if (!submitWaitlist || form.dataset.submitting === 'true') return;
  const button = form.querySelector('#submit');
  const error = form.querySelector('#error');
  const email = form.querySelector('#email');
  const consent = form.querySelector('#consent');
  if (!showEmailCheck(form, true)) { email.focus?.(); return; }
  if (!form.reportValidity()) return;
  if (!consent.checked) { error.textContent = 'Please confirm consent.'; return; }
  form.dataset.submitting = 'true';
  button.disabled = true;
  button.textContent = 'Joining…';
  error.textContent = '';
  try {
    const result = await submitWaitlist({
      email: email.value.trim(), consent: true, noticeVersion: NOTICE_VERSION,
      website: form.querySelector('#website').value,
    });
    if (result?.ok !== true) throw new Error('Registration was not confirmed.');
    if (!form.isConnected) return;
    form.innerHTML = '<div class="result-icon">✓</div><h3 role="status">You’re on the list.</h3><p class="muted">Your request has been saved. This does not create a wallet or guarantee an invitation.</p><p class="muted">While you wait, try the free tools:</p><div class="joined-links"><a class="tour-chip" href="#security/backup">Check your backup</a><a class="tour-chip" href="#security/sheet">Backup instructions sheet</a><a class="tour-chip" href="#security/scam">Scam check</a><a class="tour-chip" href="#learn">Crypto glossary</a></div><a class="button wide" href="#features">Explore FYNX Wallet</a>';
  } catch {
    if (!form.isConnected) return;
    error.textContent = 'We couldn’t confirm your signup. Please try again later. If you already joined, retrying won’t create a duplicate.';
    button.disabled = false;
    button.textContent = 'Join waitlist ↗';
  } finally {
    delete form.dataset.submitting;
  }
}
// Friendly email checks shown inline under the field (the server still validates everything).
const EMAIL_TYPOS={'gmial.com':'gmail.com','gmai.com':'gmail.com','gamil.com':'gmail.com','gmail.co':'gmail.com','gmail.con':'gmail.com','gnail.com':'gmail.com','gmaill.com':'gmail.com','hotmial.com':'hotmail.com','hotmail.co':'hotmail.com','hotmai.com':'hotmail.com','yahooo.com':'yahoo.com','yaho.com':'yahoo.com','yahoo.co':'yahoo.com','outlok.com':'outlook.com','outlook.co':'outlook.com','iclod.com':'icloud.com','icloud.co':'icloud.com','icoud.com':'icloud.com'};
function emailProblem(raw){const v=String(raw||'').trim();if(!v)return'Enter your email address.';if(/\s/.test(v))return'Email addresses can’t contain spaces. Please remove them.';const at=v.split('@');if(at.length!==2)return at.length<2?'An email address needs an @, like you@example.com.':'An email address has only one @.';const [local,domain]=at;if(!local)return'Add the part before the @, like you@example.com.';if(!domain)return'Add the part after the @, like example.com.';if(!/^[^.]+(\.[^.]+)+$/.test(domain)||!/\.[a-z]{2,}$/i.test(domain))return`Check the part after the @: “${domain}” should look like example.com.`;if(v.length>254)return'That email address is too long.';return''}
function emailSuggestion(raw){const v=String(raw||'').trim(),i=v.lastIndexOf('@');if(i<1)return'';const fix=EMAIL_TYPOS[v.slice(i+1).toLowerCase()];return fix?`${v.slice(0,i)}@${fix}`:''}
function showEmailCheck(form,strict){const email=form.querySelector('#email'),error=form.querySelector('#error'),hint=form.querySelector('#email-hint');if(!email)return true;const problem=emailProblem(email.value),suggest=problem?'':emailSuggestion(email.value);if(email.setAttribute){if(problem&&strict)email.setAttribute('aria-invalid','true');else email.removeAttribute('aria-invalid')}if(error&&strict)error.textContent=problem;if(hint){hint.innerHTML=suggest?`Did you mean <b>${escape(suggest)}</b>? <button type="button" class="linkbutton" id="email-fix">Use this</button>`:'';const fix=form.querySelector('#email-fix');if(fix)fix.addEventListener('click',()=>{email.value=suggest;hint.innerHTML='';if(error)error.textContent='';email.removeAttribute?.('aria-invalid');email.focus?.()})}return!problem}
function bindWaitlistForm(form){const email=form.querySelector('#email'),error=form.querySelector('#error');if(!email||!email.addEventListener)return;email.addEventListener('blur',()=>{if(email.value.trim())showEmailCheck(form,true)});email.addEventListener('input',()=>{if(email.getAttribute('aria-invalid')==='true'&&!emailProblem(email.value)){email.removeAttribute('aria-invalid');if(error)error.textContent=''}showEmailCheck(form,false)})}
function intro(title,sub,content){return `<div class="app-header"><div><span class="eyebrow">FYNX WALLET / COMING SOON</span><h1>${title}</h1><p>${sub}</p></div></div>${content}`}
const features=[['One clear portfolio.','A planned view of your balances, assets, and transactions across supported networks.','portfolio'],['Buy and sell, simply.','Proposed card and bank purchase flows through approved third-party payment providers.','buy'],['More ways to move.','Send, receive, and swap supported crypto assets with clear network and fee review.','send']];
