function home(){return `<section class="hero"><div><span class="pill">A new chapter for FYNX · In development</span><h1>Your crypto.<br>Simply yours.</h1><p>A little less complexity. A lot more possibility. Discover a calmer place for your digital assets.</p><div class="cta">${button('Join the waitlist ↗')}${button('Explore the product','features','light')}</div><span class="tiny">Coming soon. No wallets or real transactions are available yet.</span></div><div class="hero-art"><div class="hero-wallet"><div class="between"><span class="tiny">A look at what’s next</span><span class="pill">Illustrative preview</span></div><div class="amount">$24,582.42</div><span class="tiny">Example portfolio · sample balances</span><div class="mini-actions"><a href="#waitlist">+ Buy</a><a href="#waitlist">↗ Send</a><a href="#waitlist">⇄ Swap</a></div>${[['₿','Bitcoin','BTC','10,420.00'],['♦','Ethereum','ETH','7,840.00'],['≋','Solana','SOL','3,322.00'],['$','USD Coin','USDC','3,000.42']].map(([i,n,s,v])=>`<a class="setting-row" href="#waitlist"><span class="flex"><span class="coin ${s.toLowerCase()}">${i}</span><span>${n}<span class="asset-ticker">${s} · ${['BTC','SOL'].includes(s)?'later, separate work':'planned first'}</span></span></span><span>$${v}</span></a>`).join('')}</div></div></section><section class="soft-section"><div class="sectiontop"><h2>Everything has its place.</h2><a class="textlink" href="#features">Explore features ↗</a></div><div class="feature-grid">${features.map(([t,d,id])=>`<article class="feature"><h3>${t}</h3><p>${d}</p><a class="textlink" href="#features/${id}">See how it works ↗</a></article>`).join('')}</div></section>${startHere()}<section class="tour"><div><span class="eyebrow">BUILT WITH A CLEAR DIRECTION</span><h2 style="margin-top:18px">Your next move<br>starts here.</h2><p class="muted">Join the waitlist to hear when access becomes available.</p>${button('Keep me in the loop ↗')}</div><div class="steps"><div class="step"><span class="number">01</span><div><b>Discover the experience</b><span class="muted">Read about the proposed product and networks.</span></div></div><div class="step"><span class="number">02</span><div><b>Join the waitlist</b><span class="muted">Share an email for future availability updates.</span></div></div><div class="step"><span class="number">03</span><div><b>Get an invitation when ready</b><span class="muted">Timing and eligibility are still to be confirmed.</span></div></div></div></section>`}
function waitlist(login=false){const ready=!!submitWaitlist;return intro(login?'You’re a little early.':'Be part of what’s next.',login?'FYNX Wallet is not open for public accounts yet. Join the waitlist for launch updates.':'Leave your email to request future availability updates.',`<div class="trade-layout"><div class="trade-intro"><h2>A calmer crypto experience is on its way.</h2><p>Explore the public pages now. Wallet access will open after testing, provider approvals, and launch preparation.</p><div class="info-box">Joining the waitlist does not create a wallet or financial account, guarantee access, or commit you to a purchase.</div></div><div class="trade-box"><h3>Join the FYNX Wallet waitlist</h3><form id="waitlist-form"><label class="label" for="email">Email address</label><input class="control" id="email" type="email" autocomplete="email" maxlength="254" placeholder="you@example.com" aria-describedby="email-hint error" required><p class="hint email-hint" id="email-hint" aria-live="polite"></p><label class="label" style="display:flex;gap:10px;align-items:start"><input id="consent" type="checkbox" required><span>I agree to receive FYNX Wallet availability updates and have read the <a style="text-decoration:underline" href="#privacy">waitlist privacy notice</a>.</span></label><input name="website" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-10000px" id="website"><p class="error" id="error" role="alert"></p><button class="button wide" id="submit" ${ready?'':'disabled'}>${ready?'Join waitlist ↗':connectError?'Temporarily unavailable':waitlistBackendReady?'Connecting…':'Waitlist unavailable'}</button><p class="hint">${ready?'Only your email is needed. We’ll confirm here after your request is saved. No confirmation email is sent.':connectError?'The waitlist service is temporarily unavailable. Please return later.':waitlistBackendReady?'Connecting securely. Your request will be saved only after you submit the form.':'Registration is not available yet. Please return shortly; no signup has been saved.'}</p></form></div></div>${whatNext()}${login?'':startHere('While you wait: free tools for any wallet')}`)}
function privacy(){return intro('Your email. A clear purpose.','Waitlist privacy notice · prelaunch-v2 · October 17, 2026.',`<article class="longform"><h2>Who manages the waitlist</h2><p>FYNX finance world inc. manages the FYNX Wallet availability waitlist. Contact <a href="mailto:fynxteam5@gmail.com">fynxteam5@gmail.com</a> with questions about your information.</p><h2>What we collect</h2><p>The form saves your email address, your consent and notice version, the registration time, a website source label, a waiting status, and an expiry date. It does not create a wallet or collect passwords, private keys, identity documents, or payment details.</p><h2>Purpose and service providers</h2><p>We use your email to manage the waitlist and send FYNX Wallet availability updates with your consent. Joining does not automatically send a confirmation email or guarantee access. Records are stored in Google Cloud Firestore in the United States and are accessible only to authorized operators. Firebase App Check and Google reCAPTCHA Enterprise process technical information to protect the form from abuse. Google Fonts supplies typography, and GitHub Pages hosts this website.</p><p>This site is protected by reCAPTCHA and the Google <a href="https://policies.google.com/privacy" target="_blank" rel="noopener">Privacy Policy</a> and <a href="https://policies.google.com/terms" target="_blank" rel="noopener">Terms of Service</a> apply.</p><h2>Retention</h2><p>Registration records expire 365 days after signup and are queued for automatic deletion, normally within 24 hours after expiry. Repeat submissions do not extend this period. Deleted data may remain in restricted backups until those backups expire.</p><h2>Withdraw consent or request deletion</h2><p>Email <a href="mailto:fynxteam5@gmail.com?subject=FYNX%20Wallet%20waitlist%20removal">fynxteam5@gmail.com</a> from the registered address with the subject “FYNX Wallet waitlist removal” to withdraw consent and request deletion. The team will remove your address from the active waitlist before sending further updates. Do not send passwords, keys, or identity documents. Any future availability email must also provide an unsubscribe option.</p>${button('Back to waitlist')}</article>`)}
