const FREE_HOSTS=['github.io','vercel.app','netlify.app','pages.dev','web.app','firebaseapp.com','herokuapp.com','glitch.me','replit.app','webflow.io','wixsite.com','blogspot.com','gitbook.io','framer.website','weebly.com','000webhostapp.com','ipfs.io','dweb.link'];
