function siteDomain(host){const parts=host.split('.');for(const s of SHARED_SUFFIXES){const n=s.split('.').length;if(host===s)return host;if(host.endsWith(`.${s}`))return parts.slice(-(n+1)).join('.')}return parts.slice(-2).join('.')}
// Edit distance counting a swap of two neighbouring letters as one edit (coinbsae → coinbase).
function editDistance(a,b){if(Math.abs(a.length-b.length)>2)return 3;const d=[...Array(a.length+1)].map((_,i)=>[i,...Array(b.length).fill(0)]);for(let j=0;j<=b.length;j++)d[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++){d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])d[i][j]=Math.min(d[i][j],d[i-2][j-2]+1)}return d[a.length][b.length]}
const unconfuse=s=>s.replace(/rn/g,'m').replace(/vv/g,'w').replace(/0/g,'o').replace(/[1|]/g,'l').replace(/3/g,'e').replace(/5/g,'s').replace(/-/g,'');
