  if(/^(javascript|data|vbscript|file|blob):/i.test(text))return{kind:'danger',title:'Do not open this.',findings:[['danger','This is not a normal web address. It can run code or open a hidden file in your browser. Real wallet services never send links like this.']]};
  const scheme=/^([a-z][a-z0-9+.-]*):\/\//i.exec(text);if(scheme&&!/^https?$/i.test(scheme[1]))return{kind:'warn',title:'This is not a website link.',findings:[['warn',`It starts with “${escape(scheme[1])}://”, which opens an app instead of a web page. Only open app links you expected, from an app you installed yourself.`]]};
  let url;try{url=new URL(scheme?text:`https://${text}`)}catch{return{kind:'warn',title:'That doesn’t look like a web address.',findings:[['warn','Paste the whole link, for example https://example.com/page. Spaces and missing parts make a link invalid.']]}}
  const host=url.hostname.toLowerCase().replace(/\.$/,''),findings=[],add=(k,t)=>findings.push([k,t]);
