function linkResultHtml(r){return `<b>${escape(r.title)}</b>${r.host?`<p class="link-real">You would actually be visiting: <code>${escape(r.domain||r.host)}</code>${r.domain&&r.domain!==r.host?` <span class="tiny">(full address ${escape(r.host)})</span>`:''}</p>`:''}<ul class="link-findings">${r.findings.map(([k,t])=>`<li class="${k}">${t}</li>`).join('')}</ul>`}
function linkSection(){return `<section class="card scam-check addr-tool" id="sec-link" aria-labelledby="link-h"><span class="eyebrow">SAFETY CHECK</span><h2 id="link-h">Check a website link</h2><p class="muted">Got a link in a message, email or ad? Paste it here before you open it. This only reads the text of the address: the link is not opened, visited or sent anywhere.</p><label class="label" for="link-input">Link or web address</label><div class="addr-row"><input class="control" id="link-input" type="text" inputmode="url" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="e.g. https://metamask.io-wallet-sync.com/restore"><button class="button light" type="button" id="link-clear">Clear</button></div><div class="addr-result" id="link-result" role="status" aria-live="polite"></div><details class="lookup-help"><summary>How to read any web address</summary><dl class="lookup-checks"><dt>Read from the right</dt><dd>The real site is the name just before the ending (.com, .io, .org) and before the first “/”. In <code>metamask.io.wallet-sync.com/login</code> the real site is <b>wallet-sync.com</b>, not MetaMask.</dd><dt>Everything before “@” is ignored</dt><dd>In <code>https://coinbase.com@example.net</code> your browser goes to example.net.</dd><dt>Type it yourself</dt><dd>For anything involving your wallet, type the official address or use a bookmark you made yourself. Search ads can be fake too.</dd><dt>Never type your phrase into a site</dt><dd>No website, support agent or “wallet sync” page ever needs your recovery phrase.</dd></dl><p class="hint">The list of official addresses on this page covers a few well-known services for convenience. It is not an endorsement, and it can’t be complete.</p></details></section>`}
