const SIGN_EXAMPLES=[['approve','Unlimited approval',()=>`0x095ea7b3${pad(EX_ADDR)}${'f'.repeat(64)}`],['revoke','Revoke an approval',()=>`0x095ea7b3${pad(EX_ADDR)}${pad('0')}`],['nft','NFT “approve all”',()=>`0xa22cb465${pad(EX_ADDR)}${pad('1')}`],['permit','Signed permit',()=>JSON.stringify({types:{EIP712Domain:[],Permit:[]},primaryType:'Permit',domain:{name:'USD Coin',version:'2',chainId:1,verifyingContract:'0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48'},message:{owner:EX_ME,spender:`0x${EX_ADDR}`,value:MAX_UINT.toString(),nonce:'0',deadline:MAX_UINT.toString()}},null,2)],['listing','Zero-price listing',()=>JSON.stringify({primaryType:'OrderComponents',domain:{name:'Seaport',version:'1.6',chainId:1},message:{offerer:EX_ME,offer:[{itemType:2,token:'0x9999999999999999999999999999999999999999',identifierOrCriteria:'1234',startAmount:'1',endAmount:'1'}],consideration:[{itemType:0,token:'0x0000000000000000000000000000000000000000',identifierOrCriteria:'0',startAmount:'1',endAmount:'1',recipient:`0x${EX_ADDR}`}],endTime:'253402300799'}},null,2)],['login','Sign-in message',()=>`example.com wants you to sign in with your Ethereum account:\n${EX_ME}\n\nSign in to Example.\n\nURI: https://example.com\nVersion: 1\nChain ID: 1\nNonce: 32891756\nIssued At: 2026-11-05T10:00:00Z`]];
function signSection(){return `<section class="card scam-check addr-tool" id="sec-sign" aria-labelledby="sign-h"><span class="eyebrow">SAFETY CHECK</span><h2 id="sign-h">Understand a signature request</h2><p class="muted">Before you press “Confirm” or “Sign” in a wallet, copy what it asks you to sign and paste it here: the “Data” or “Hex” field of a transaction, the full request of a signature, or the message text. This page explains the most common requests in plain words. Nothing is signed, sent or saved.</p><div class="tour-jump sign-examples" role="group" aria-label="Load an example"><span class="tiny jump-label">Try an example</span>${SIGN_EXAMPLES.map(([id,name])=>`<button type="button" class="tour-chip" data-example="${id}">${name}</button>`).join('')}</div><label class="label" for="sign-input">What your wallet asks you to sign</label><textarea class="control sign-input" id="sign-input" rows="5" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="0x095ea7b3…  or  { &quot;domain&quot;: …, &quot;message&quot;: … }  or the message text"></textarea><div class="sign-actions"><span class="hint" id="sign-example-note"></span><button class="button light" type="button" id="sign-clear">Clear</button></div><div class="addr-result" id="sign-result" role="status" aria-live="polite"></div><details class="lookup-help"><summary>The four kinds of request, and where to find the data</summary><dl class="lookup-checks"><dt>Transaction</dt><dd>Happens on the blockchain and costs a network fee. Most wallets show the details under a “Data”, “Hex” or “Details” tab on the confirmation screen. The coin amount you send with it is shown separately as the value.</dd><dt>Typed signature (permit, listing)</dt><dd>Free and invisible at first, but it can authorise someone to take tokens or sell your items later. Expand the message in your wallet to copy it.</dd><dt>Plain message or sign-in</dt><dd>Readable text. It cannot move funds on its own; check the site named in it.</dd><dt>Raw code (hash)</dt><dd>A bare 64-character code with no explanation. Refuse it: it is “blind signing”.</dd></dl><p class="hint">This check reads common token, NFT and marketplace formats only. It can’t tell whether a contract is honest, and some swaps and multi-step actions can’t be read here. When in doubt, don’t sign. Example requests use made-up addresses.</p></details></section>`}
function bindSignTool(){const input=$('#sign-input'),out=$('#sign-result'),clear=$('#sign-clear'),note=$('#sign-example-note');if(!input||!out)return;
  const show=()=>{const r=signCheck(input.value);if(!r){out.innerHTML='';out.className='addr-result';return}if(r.clear)input.value='';out.className=`addr-result ${r.kind}`;out.innerHTML=signResultHtml(r)};
  input.addEventListener('input',()=>{if(note)note.textContent='';show()});if(clear)clear.addEventListener('click',()=>{input.value='';if(note)note.textContent='';show();input.focus()});
  const root=$('#app');if(root&&root.querySelectorAll)for(const b of root.querySelectorAll('.sign-examples [data-example]'))b.addEventListener('click',()=>{const ex=SIGN_EXAMPLES.find(([id])=>id===b.dataset.example);if(!ex)return;input.value=ex[2]();if(note)note.textContent=`Example: ${ex[1]} (made-up addresses)`;show()})}
const learnTopics=[['basics','Basics'],['keys','Keys and safety'],['sending','Sending and fees'],['tokens','Tokens and swaps'],['buying','Buying and selling']];
