const glossaryMap=new Map(glossary.map(g=>[g[0],g]));
function learnPage(){return intro('Crypto words, explained.','A plain-English glossary of the terms you will meet in any wallet. Education only, not financial advice.',`<div class="faq-tools"><label class="sr-only" for="learn-search">Search the glossary</label><input class="control faq-search" id="learn-search" type="search" placeholder="Search terms, e.g. gas, seed phrase, approval" autocomplete="off"></div><div class="tour-jump learn-topics" role="group" aria-label="Filter by topic"><button type="button" class="tour-chip" data-topic="" aria-pressed="true">All</button>${learnTopics.map(([id,name])=>`<button type="button" class="tour-chip" data-topic="${id}" aria-pressed="false">${name}</button>`).join('')}</div><p class="hint faq-count" id="learn-count" role="status" aria-live="polite">${glossary.length} terms</p>${learnTopics.map(([id,name])=>`<section class="faq-group learn-group" data-topic="${id}" aria-labelledby="lt-${id}"><h2 id="lt-${id}">${name}</h2><div class="learn-grid">${glossary.filter(g=>g[2]===id).map(([slug,term,,def,aka,rel,link])=>`<article class="card term" id="term-${slug}" data-topic="${id}" data-search="${escape(`${term} ${def} ${aka}`.toLowerCase())}"><h3>${term}</h3><p>${def}</p>${rel.length?`<p class="term-related">Related: ${rel.map(r=>`<a href="#learn/${r}">${glossaryMap.get(r)[1]}</a>`).join(', ')}</p>`:''}<div class="term-foot">${link?`<a class="textlink" href="#${link[0]}">${link[1]} ↗</a>`:'<span></span>'}<button type="button" class="term-copy" data-slug="${slug}" aria-label="Copy link to ${escape(term)}">Copy link</button></div></article>`).join('')}</div></section>`).join('')}<div class="faq-empty" id="learn-empty" hidden><p>No terms match. Try a shorter word, or <a href="#faq">browse the Questions page</a>.</p></div><div class="info-box">These explanations are general education about how crypto wallets work. They are not financial, legal or tax advice, and they describe no live FYNX service. ${button('Join the waitlist ↗','waitlist','light')}</div>`)}
function shareLink(path){return `${location.href.split('#')[0]}#${path}`}
async function copyShareLink(btn,path){const url=shareLink(path),done=t=>{btn.textContent=t;setTimeout(()=>{btn.textContent='Copy link'},2000)};try{await navigator.clipboard.writeText(url);done('Link copied')}catch{history.replaceState(null,'',`#${path}`);done('Link in address bar')}}
function highlight(el){if(!el)return;el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),2200)}
function bindLearn(section=''){const root=$('#app'),input=$('#learn-search');if(!input||!root.querySelectorAll)return;const cards=[...root.querySelectorAll('.term')],chips=[...root.querySelectorAll('.learn-topics .tour-chip')];let topic='';
  const apply=()=>{const terms=input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);let shown=0;for(const c of cards){const hit=(!topic||c.dataset.topic===topic)&&terms.every(t=>c.dataset.search.includes(t));c.hidden=!hit;if(hit)shown++}for(const g of root.querySelectorAll('.learn-group'))g.hidden=![...g.querySelectorAll('.term')].some(c=>!c.hidden);$('#learn-empty').hidden=shown>0;$('#learn-count').textContent=shown===cards.length?`${cards.length} terms`:`${shown} of ${cards.length} terms`};
  input.addEventListener('input',apply);
  for(const chip of chips)chip.addEventListener('click',()=>{topic=chip.dataset.topic;for(const c of chips)c.setAttribute('aria-pressed',String(c===chip));apply()});
  root.addEventListener('click',e=>{const b=e.target.closest('.term-copy');if(b)copyShareLink(b,`learn/${b.dataset.slug}`)});
  if(section)requestAnimationFrame(()=>{const t=document.getElementById(`term-${section}`);goToSection(t,false);const h=t&&t.querySelector('h3');if(h){h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}highlight(t)})}
const closedRoute=r=>['wallet','assets','activity','swap','send','receive','settings','buy','sell','login'].includes(r)||r.startsWith('asset/')||r.startsWith('transaction/');
const featureSections=()=>[...featureTour.map(([id])=>id),'review'];
const pageSections={security:['scam','link','approve','sign','backup','sheet'],networks:['plan','check','lookup','units']};
const sectionNames={networks:[['plan','Planned support'],['check','Address checker'],['lookup','Transaction lookup'],['units','Units and fees']],security:[['scam','Is this a scam?'],['link','Check a link'],['approve','Before you approve'],['sign','Read a signature'],['backup','Backup check'],['sheet','Family backup sheet']]};
function pageJump(page,prefix){return `<nav class="tour-jump page-jump" aria-label="On this page"><span class="tiny jump-label">On this page</span>${sectionNames[page].map(([id,name])=>`<a class="tour-chip" href="#${page}/${id}" data-target="${prefix}-${id}">${name}</a>`).join('')}</nav>`}
function bindSections(section,prefix,page){const root=$('#app');if(page&&root&&root.querySelectorAll)for(const chip of root.querySelectorAll('.page-jump a[data-target]'))chip.addEventListener('click',e=>{e.preventDefault();goToSection(document.getElementById(chip.dataset.target));try{history.replaceState(null,'',chip.getAttribute('href'))}catch{}});if(section)requestAnimationFrame(()=>goToSection(document.getElementById(`${prefix}-${section}`),false))}
// "Back to top" control for long pages; created once, shown after scrolling well down.
function setupBackToTop(){if(!document.body||!document.createElement)return;const b=document.createElement('button');b.type='button';b.className='back-top';b.hidden=true;b.textContent='↑ Top';b.setAttribute('aria-label','Back to top');b.addEventListener('click',()=>{window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});focusPageHeading()});document.body.appendChild(b);const update=()=>{b.hidden=window.scrollY<900};window.addEventListener('scroll',update,{passive:true});window.addEventListener('hashchange',update);update()}
// Block-explorer lookup (#networks/lookup). Only builds links to public explorers; nothing is sent until the visitor opens one.
const EXPLORERS={
  evm:[['Ethereum','https://etherscan.io'],['Base','https://basescan.org'],['Ethereum Sepolia (test)','https://sepolia.etherscan.io'],['Base Sepolia (test)','https://sepolia.basescan.org']],
  btc:[['Bitcoin','https://mempool.space'],['Bitcoin testnet4 (test)','https://mempool.space/testnet4'],['Bitcoin testnet3 (test)','https://mempool.space/testnet']],
  sol:[['Solana','https://explorer.solana.com',''],['Solana devnet (test)','https://explorer.solana.com','?cluster=devnet']],
};
const SECRET_NOTE='A private key can look exactly like this. Only continue if you copied it from a wallet’s activity list, a receipt or a block explorer, never from a backup, “export key” or “show private key” screen.';
function explorerLinks(kind,path,value,only){const list=EXPLORERS[kind].filter(([n])=>!only||only.test(n));return list.map(([name,base,query=''])=>[name,`${base}/${path}/${encodeURIComponent(value)}${query}`])}
// Explorer links pasted into the lookup (#networks/lookup): exact host match only, so look-alike domains are never trusted.
const EXPLORER_HOSTS={'etherscan.io':'Ethereum','sepolia.etherscan.io':'Ethereum Sepolia (test)','basescan.org':'Base','sepolia.basescan.org':'Base Sepolia (test)','mempool.space':'Bitcoin','blockstream.info':'Bitcoin','explorer.solana.com':'Solana','solscan.io':'Solana'};
function explorerFromUrl(v){if(!/^https?:\/\//i.test(v)&&!/^(www\.)?[a-z0-9-]+(\.[a-z0-9-]+)+\//i.test(v))return null;
  const m=/^(?:https?:\/\/)?([^\/?#\s]+)(\/[^?#\s]*)?(\?[^#\s]*)?(#\S*)?$/i.exec(v);if(!m)return{unknown:true,host:''};
  const host=m[1].toLowerCase().replace(/^www\./,'').replace(/:\d+$/,''),path=(m[2]||'/').split('/').filter(Boolean),query=m[3]||'';let network=EXPLORER_HOSTS[host];if(!network)return{unknown:true,host};
  if(host==='mempool.space'||host==='blockstream.info'){if(path[0]==='testnet4'){network='Bitcoin testnet4 (test)';path.shift()}else if(path[0]==='testnet'){network='Bitcoin testnet3 (test)';path.shift()}}
  if(network==='Solana'&&/[?&]cluster=devnet(&|$)/i.test(query))network='Solana devnet (test)';
  const i=path.findIndex(x=>/^(tx|address|account)$/i.test(x)),value=i>=0&&path[i+1]?(()=>{try{return decodeURIComponent(path[i+1])}catch{return path[i+1]}})():'';
  return value?{network,host,value,kind:/^tx$/i.test(path[i])?'tx':'address'}:{network,host,value:''}}
function lookupTarget(raw){const v=String(raw||'').trim();if(!v)return null;const link=explorerFromUrl(v);if(!link)return lookupPlain(v);
  if(link.unknown)return{kind:'warn',title:'This link is not from a recognised block explorer.',body:`${link.host?`“${link.host}” is not one of the explorers this tool knows (Etherscan, Basescan, mempool.space, Blockstream, Solana Explorer, Solscan). `:''}Scam sites copy explorer pages on look-alike addresses. Paste just the transaction ID or address instead, and check the website address letter by letter.`,links:[]};
  if(!link.value)return{kind:'warn',title:`A ${link.network} explorer link, but no transaction or address was found in it.`,body:'Copy the link of a transaction or address page (it contains /tx/ or /address/), or paste the ID itself.',links:[]};
  const r=lookupPlain(link.value);if(!r||r.kind!=='ok')return r;
  const own=r.links.filter(([n])=>n===link.network);if(!own.length)return{kind:'warn',title:'The link and its contents do not match.',body:`The link is for ${link.network}, but what it contains does not look like a ${link.network} ${link.kind==='tx'?'transaction ID':'address'}. Copy the link again from the explorer, or paste the ID itself.`,links:[]};
  return{...r,secret:false,found:link.value,network:link.network,title:`${r.title} From a ${link.network} explorer link.`,links:[...own,...r.links.filter(([n])=>n!==link.network)]}}
function lookupPlain(v){
  const words=v.split(/\s+/);if(words.length>=12&&words.every(w=>/^[a-z]+$/i.test(w)))return{kind:'danger',title:'Stop: this looks like a recovery phrase.',body:'Never paste a recovery phrase into any website, chat or search box, and never look it up anywhere. Anyone who has it can take everything in that wallet. The field has been cleared.',clear:true,links:[]};
  if(/^xprv[1-9A-HJ-NP-Za-km-z]{100,}$/.test(v)||/^[5KL][1-9A-HJ-NP-Za-km-z]{50,51}$/.test(v))return{kind:'danger',title:'Stop: this looks like a private key.',body:'This has the format of a Bitcoin private key. It must never be pasted into a website or shared with anyone, including support staff. The field has been cleared. If someone asked you for it, treat it as a scam.',clear:true,links:[]};
  if(/\s/.test(v))return{kind:'warn',title:'Paste one thing at a time.',body:'Transaction IDs, addresses and names contain no spaces.',links:[]};
  if(/^xpub[1-9A-HJ-NP-Za-km-z]{100,}$/.test(v))return{kind:'warn',title:'This is an extended public key (xpub).',body:'It cannot move funds, but it reveals every address and the full history of that wallet. Share it only with services you trust. Look up a single address instead.',links:[]};
  if(/^0x[0-9a-f]{64}$/i.test(v))return{kind:'ok',type:'Transaction ID',title:'Ethereum-style transaction ID.',body:'0x followed by 64 characters is a transaction ID on Ethereum, Base and other EVM networks. The same ID exists on only one network: if one explorer says “not found”, try the network you sent on.',secret:true,links:explorerLinks('evm','tx',v)};
  if(/^0x[0-9a-f]{40}$/i.test(v)){const body=v.slice(2),mixed=/[a-f]/.test(body)&&/[A-F]/.test(body);if(mixed&&checksumAddress(v)!==`0x${body}`)return{kind:'danger',title:'Checksum does not match: likely a typo.',body:'The capital letters in this address do not match the Ethereum checksum, so a character was probably mistyped or changed. Copy it again from the source before looking it up or sending anything.',links:[]};
    return{kind:'ok',type:'Address',title:'Ethereum-style (EVM) address.',body:'The same address can exist on Ethereum, Base and other EVM networks, each with its own balance and history. Open the network you are interested in.',links:explorerLinks('evm','address',v)}}
  if(/^0x/i.test(v))return{kind:'warn',title:'Incomplete or damaged.',body:`An Ethereum-style address has 40 characters after 0x and a transaction ID has 64. This has ${v.length-2}${/^0x[0-9a-f]*$/i.test(v)?'':' and contains characters that are not allowed'}. Copy it again from the source.`,links:[]};
  if(/^[a-z0-9-]+(\.[a-z0-9-]+)*\.eth$/i.test(v))return{kind:'ok',type:'Name',title:'An ENS name (a name that points to an address).',body:'The owner can change which address a name points to. Look it up, then compare the full address with the recipient before sending.',links:[['ENS app',`https://app.ens.domains/${encodeURIComponent(v.toLowerCase())}`],['Ethereum (Etherscan)',`https://etherscan.io/name-lookup-search?id=${encodeURIComponent(v.toLowerCase())}`]]};
  if(/^[0-9a-f]{64}$/i.test(v))return{kind:'ok',type:'Transaction ID',title:'Bitcoin-style transaction ID.',body:'64 characters without 0x is the format of a Bitcoin transaction ID. Bitcoin explorers show whether it is confirmed and how many blocks have followed it.',secret:true,links:explorerLinks('btc','tx',v.toLowerCase())};
  if(/^(bc1|BC1)[02-9ac-hj-np-zAC-HJ-NP-Z]{11,71}$/.test(v)&&(v===v.toLowerCase()||v===v.toUpperCase()))return{kind:'ok',type:'Address',title:'Bitcoin address (modern format).',body:'Addresses starting with bc1 exist only on the Bitcoin network.',links:explorerLinks('btc','address',v.toLowerCase(),/^Bitcoin$/)};
  if(/^(tb1|TB1)[02-9ac-hj-np-zAC-HJ-NP-Z]{11,71}$/.test(v)&&(v===v.toLowerCase()||v===v.toUpperCase()))return{kind:'warn',type:'Address',title:'Bitcoin test-network address.',body:'Addresses starting with tb1 are for Bitcoin test networks, which have no real value.',links:explorerLinks('btc','address',v.toLowerCase(),/test/)};
  if(new RegExp(`^[13]${B58}{25,33}$`).test(v)){const solToo=v.length>=32;return{kind:'ok',type:'Address',title:solToo?'A Bitcoin address (older format) or a Solana address.':'Bitcoin address (older format).',body:solToo?'This length is valid for both. If it came from a Bitcoin wallet, use the Bitcoin explorer; if it came from a Solana wallet, use the Solana one.':'Bitcoin addresses starting with 1 or 3 exist only on the Bitcoin network.',links:[...explorerLinks('btc','address',v,/^Bitcoin$/),...(solToo?explorerLinks('sol','address',v,/^Solana$/):[])]}}
  if(new RegExp(`^${B58}{32,44}$`).test(v))return{kind:'ok',type:'Address',title:'Solana address.',body:'Solana addresses are 32–44 letters and numbers without 0x. The same address can also be used on Solana’s test network (devnet).',links:explorerLinks('sol','address',v)};
  if(new RegExp(`^${B58}{86,88}$`).test(v))return{kind:'ok',type:'Transaction ID',title:'Solana transaction signature.',body:'Solana transaction IDs (called signatures) are 86–88 letters and numbers.',secret:true,links:explorerLinks('sol','tx',v)};
  return{kind:'warn',title:'Not a recognised transaction ID, address or name.',body:'It does not match the formats used by Ethereum, Base, Bitcoin or Solana. Copy it again from your wallet’s activity list or receipt, rather than retyping it.',links:[]}}
const explorerChecks=[['Status','Success, failed or pending. A failed transaction still costs the network fee, but nothing is moved.'],['From and to','The sending and receiving addresses. Compare every character with the ones you expected.'],['Value or tokens transferred','The asset and amount that actually moved. Token transfers are listed separately from the ETH value.'],['Network fee','What the network charged. It goes to the network, not to the recipient.'],['Confirmations or block','How deeply the transaction is buried in the chain. More confirmations means it is more settled.']];
function lookupSection(){return `<section class="net-section card addr-tool" id="net-lookup" aria-labelledby="lookup-h"><h2 id="lookup-h">Look up a transaction or address</h2><p class="muted">Paste a transaction ID, a wallet address, an ENS name or a link copied from a block explorer to open it on a public block explorer. This page only builds the links; nothing is sent anywhere until you open one, and explorers are run by other companies.</p><label class="label" for="lookup-input">Transaction ID, address or name</label><div class="addr-row"><input class="control" id="lookup-input" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="e.g. 0x… transaction ID, an address, name.eth or an explorer link"><button class="button light" type="button" id="lookup-clear">Clear</button></div><div class="addr-result" id="lookup-result" role="status" aria-live="polite"></div><details class="lookup-help"><summary>What to check on the explorer</summary><dl class="lookup-checks">${explorerChecks.map(([t,d])=>`<dt>${t}</dt><dd>${d}</dd>`).join('')}</dl><p class="hint">An explorer shows public records. It cannot tell you who owns an address, and it cannot reverse or cancel a transaction. No explorer, support agent or “recovery service” needs your recovery phrase.</p></details></section>`}
function lookupResultHtml(r,confirmed){const links=r.links.length&&(!r.secret||confirmed)?`<ul class="lookup-links">${r.links.map(([n,u])=>`<li><a class="button light" href="${escape(u)}" target="_blank" rel="noopener noreferrer">${escape(n)} ↗</a></li>`).join('')}</ul>`:'';
  const gate=r.secret?`<p class="lookup-warn">${escape(SECRET_NOTE)}</p><label class="check lookup-confirm"><input type="checkbox" id="lookup-confirm"${confirmed?' checked':''}> <span>This came from my wallet’s activity list, a receipt or an explorer.</span></label>`:'';
  const found=r.found?`<p class="lookup-found">Found in the link: <code>${escape(r.found)}</code></p>`:'';
  return `<b>${escape(r.title)}</b>${found}<p>${escape(r.body)}</p>${gate}${links}${r.links.length&&(!r.secret||confirmed)?'<small>Opens in a new tab on a third-party site that FYNX does not run.</small>':''}`}
function bindLookupTool(){const input=$('#lookup-input'),out=$('#lookup-result'),clear=$('#lookup-clear');if(!input||!out)return;let confirmed=false;
  const show=()=>{const r=lookupTarget(input.value);if(!r){out.innerHTML='';out.className='addr-result';return}if(r.clear)input.value='';out.className=`addr-result ${r.kind}`;out.innerHTML=lookupResultHtml(r,confirmed);const box=out.querySelector&&out.querySelector('#lookup-confirm');if(box)box.addEventListener('change',()=>{confirmed=box.checked;show()})};
  input.addEventListener('input',()=>{confirmed=false;show()});if(clear)clear.addEventListener('click',()=>{input.value='';confirmed=false;show();input.focus()})}
// Unit converter and network-fee arithmetic (#networks/units). Exact integer maths with BigInt; no prices.
const unitAssets=[['ETH','Ether (ETH)',[['ETH',18],['gwei',9],['wei',0]],'ETH has 18 decimal places. 1 ETH = 1,000,000,000 gwei = 10¹⁸ wei. Network fees on Ethereum and Base are usually quoted in gwei.'],['USDC','USD Coin (USDC)',[['USDC',6],['base units',0]],'USDC uses 6 decimal places on Ethereum and Base, so 1 USDC is 1,000,000 base units. Other tokens use other decimals, which is why wallets read them from the token contract.'],['BTC','Bitcoin (BTC)',[['BTC',8],['sats',0]],'Bitcoin has 8 decimal places. 1 BTC = 100,000,000 satoshis (sats).'],['SOL','Solana (SOL)',[['SOL',9],['lamports',0]],'SOL has 9 decimal places. 1 SOL = 1,000,000,000 lamports.']];
function parseAmount(raw,decimals){let v=String(raw||'').trim().replace(/[\s_]/g,'');if(!v)return{empty:true};if(/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(v))v=v.replace(/,/g,'');else if(/^\d*,\d+$/.test(v))v=v.replace(',','.');if(v.startsWith('-'))return{error:'Amounts cannot be negative.'};if(!/^(\d+\.?\d*|\.\d+)$/.test(v))return{error:'Use numbers only, with a dot for decimals, e.g. 0.05'};const [whole,frac='']=v.split('.');if(frac.length>decimals)return{error:decimals?`This unit has at most ${decimals} decimal places. Anything smaller cannot exist on the network.`:'This is the smallest unit; it cannot be split, so use a whole number.'};if(whole.replace(/^0+/,'').length>40)return{error:'That number is too large.'};return{value:BigInt(whole||'0')*10n**BigInt(decimals)+BigInt((frac||'').padEnd(decimals,'0')||'0')}}
function formatUnits(base,decimals){const neg=base<0n,s=(neg?-base:base).toString().padStart(decimals+1,'0'),whole=s.slice(0,s.length-decimals).replace(/\B(?=(\d{3})+(?!\d))/g,','),frac=decimals?s.slice(s.length-decimals).replace(/0+$/,''):'';return (neg?'-':'')+whole+(frac?`.${frac}`:'')}
function convertAmount(asset,raw,unit){const a=unitAssets.find(x=>x[0]===asset);if(!a)return{error:'Unknown asset.'};const u=a[2].find(x=>x[0]===unit)||a[2][0],p=parseAmount(raw,u[1]);if(p.empty||p.error)return p;return{rows:a[2].map(([name,d])=>[name,formatUnits(p.value,d)])}}
function feeEstimate(gasRaw,gweiRaw){const g=String(gasRaw||'').trim().replace(/[,\s_]/g,'');if(!g&&!String(gweiRaw||'').trim())return{empty:true};if(!/^\d+$/.test(g)||g.length>12)return{error:'Gas used must be a whole number, such as 21000.'};const p=parseAmount(gweiRaw,9);if(p.empty)return{error:'Enter a gas price in gwei, as shown by your wallet.'};if(p.error)return{error:`Gas price: ${p.error}`};const wei=BigInt(g)*p.value;return{wei,eth:formatUnits(wei,18),gwei:formatUnits(wei,9)}}
function unitsSection(){return `<section class="net-section card addr-tool" id="net-units" aria-labelledby="units-h"><h2 id="units-h">Convert amounts and understand fees</h2><p class="muted">Wallets and explorers show the same amount in different units. Convert between them exactly, and see how a network fee is worked out. Pure arithmetic in your browser: no prices, nothing sent.</p><div class="units-grid"><div><h3>Unit converter</h3><label class="label" for="units-asset">Asset</label><select class="control" id="units-asset">${unitAssets.map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select><label class="label" for="units-amount">Amount</label><div class="addr-row"><input class="control" id="units-amount" type="text" inputmode="decimal" autocomplete="off" placeholder="e.g. 0.05"><label class="sr-only" for="units-unit">Unit</label><select class="control units-unit" id="units-unit"></select></div><div class="units-out" id="units-out" role="status" aria-live="polite"></div><p class="hint" id="units-note"></p></div><div><h3>Network fee arithmetic</h3><p class="muted">On Ethereum, a fee is the gas used multiplied by the gas price. A plain ETH transfer always uses 21,000 gas; token transfers and swaps use more, and your wallet shows the exact figure.</p><label class="label" for="fee-gas">Gas used</label><input class="control" id="fee-gas" type="text" inputmode="numeric" autocomplete="off" value="21000"><label class="label" for="fee-gwei">Gas price (gwei)</label><input class="control" id="fee-gwei" type="text" inputmode="decimal" autocomplete="off" placeholder="from your wallet, e.g. 1.5"><div class="units-out" id="fee-out" role="status" aria-live="polite"></div><p class="hint">Example arithmetic, not a live fee: gas prices change every block. On Base and other layer-2 networks the total also includes a small data fee for posting to Ethereum, so your wallet’s figure can be higher.</p></div></div></section>`}
function unitsTable(rows){return `<table class="units-table"><tbody>${rows.map(([n,v])=>`<tr><th scope="row">${escape(n)}</th><td>${escape(v)}</td></tr>`).join('')}</tbody></table>`}
function bindUnitsTool(){const asset=$('#units-asset'),amount=$('#units-amount'),unit=$('#units-unit'),out=$('#units-out'),note=$('#units-note'),gas=$('#fee-gas'),gwei=$('#fee-gwei'),feeOut=$('#fee-out');if(!asset||!amount||!unit||!out)return;
  const fillUnits=()=>{const a=unitAssets.find(x=>x[0]===asset.value)||unitAssets[0];unit.innerHTML=a[2].map(([n])=>`<option value="${n}">${n}</option>`).join('');if(note)note.textContent=a[3]};
  const show=()=>{const r=convertAmount(asset.value,amount.value,unit.value);out.className=`units-out${r.error?' warn':''}`;out.innerHTML=r.empty?'':r.error?escape(r.error):unitsTable(r.rows)};
  const showFee=()=>{if(!gas||!gwei||!feeOut)return;const r=feeEstimate(gas.value,gwei.value);feeOut.className=`units-out${r.error&&String(gwei.value).trim()?' warn':''}`;feeOut.innerHTML=r.empty||(r.error&&!String(gwei.value).trim())?'':r.error?escape(r.error):unitsTable([['Fee in ETH',r.eth],['Fee in gwei',r.gwei],['Fee in wei',formatUnits(r.wei,0)]])};
  fillUnits();asset.addEventListener('change',()=>{fillUnits();show()});unit.addEventListener('change',show);amount.addEventListener('input',show);if(gas)gas.addEventListener('input',showFee);if(gwei)gwei.addEventListener('input',showFee)}
const sitePages=[['features','Features','A tour of the proposed wallet, with an example review screen.'],['networks','Networks','Planned networks, an address checker, a transaction lookup and a unit and fee converter.'],['security','Security','A scam self-check, a recovery-phrase backup check, a printable backup instructions sheet and what to verify before approving.'],['faq','Questions','Searchable answers about the waitlist and product.'],['learn','Glossary','Plain-English crypto terms, searchable by topic.'],['waitlist','Join the waitlist','Request availability updates by email.'],['privacy','Waitlist privacy','What the waitlist keeps and for how long.']];
function notFound(){return intro('This page doesn’t exist.','The link may be mistyped or out of date. Nothing is wrong with your browser.',`<nav class="security-grid notfound-links" aria-label="Pages on this site">${sitePages.map(([h,t,d])=>`<a class="card security-card" href="#${h}"><h3>${t} ↗</h3><p>${d}</p></a>`).join('')}</nav><div class="info-box">Looking for a wallet account? Public accounts are not open yet. ${button('Back to the homepage','home','light')}</div>`)}
const pageTitles={notfound:'Page not found',home:'',features:'Features',networks:'Networks',security:'Security',waitlist:'Join the waitlist',login:'Log in',privacy:'Waitlist privacy',terms:'Preview terms',faq:'Questions',learn:'Crypto glossary'};
function syncPageChrome(r){for(const link of document.querySelectorAll('.mobilenav a')){if(link.getAttribute('href')===`#${r}`)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')}document.title=pageTitles[r]?`${pageTitles[r]} · FYNX Wallet`:'FYNX Wallet — Your crypto. Simply yours.';for(const link of document.querySelectorAll('.globalnav a')){const current=link.getAttribute('href')===`#${r}`;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')}}
function setFooterYear(){const y=document.querySelector('[data-year]');if(y)y.textContent=String(new Date().getFullYear())}
function focusPageHeading(){const heading=document.querySelector('#app h1');if(!heading)return;heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}
function render(){let r=location.hash.slice(1)||'home',content,section='';const deep=/^features\/([a-z]+)$/.exec(r);if(deep&&featureSections().includes(deep[1])){section=deep[1];r='features'}const part=/^(security|networks)\/([a-z]+)$/.exec(r);if(part&&pageSections[part[1]].includes(part[2])){section=part[2];r=part[1]}const sub=/^(learn|faq)\/([a-z0-9-]+)$/.exec(r);if(sub&&(sub[1]==='learn'?glossaryMap.has(sub[2]):faqSlugs().includes(sub[2]))){section=sub[2];r=sub[1]}if(r!=='home'&&!closedRoute(r)&&!Object.hasOwn(pageTitles,r))r='notfound';if(closedRoute(r))r='login';syncPageChrome(r);if(r==='notfound')content=notFound();else if(r==='home')content=home();else if(r==='login'||r==='waitlist')content=waitlist(r==='login');else if(r==='features')content=featuresPage();else if(r==='networks')content=networks();else if(r==='security')content=security();else if(r==='privacy')content=privacy();else if(r==='terms')content=intro('A clear starting point.','Pre-launch website notice.',`<article class="longform"><p>FYNX Wallet is in development. This website describes a proposed product. Illustrative balances and features do not represent live financial services, executable prices, or guaranteed availability.</p><p>Waitlist registration requests availability updates; it does not create a trading, payment, or custody account. Eligibility, supported regions, product terms, fees, and launch timing are not yet finalized.</p>${button('Join the waitlist')}</article>`);else if(r==='faq')content=faq();else if(r==='learn')content=learnPage();else content=waitlist(true);$('#app').innerHTML=content;if($('#waitlist-form')){$('#waitlist-form').onsubmit=handleWaitlistSubmit;bindWaitlistForm($('#waitlist-form'))}if(r==='faq')bindFaq(section);if(r==='learn')bindLearn(section);if(r==='features')bindFeatures(section);if(r==='networks'){bindAddressTool();bindLookupTool();bindUnitsTool();bindSections(section,'net','networks')}if(r==='security'){bindScamCheck();bindLinkTool();bindSignTool();bindBackupCheck();bindPlanSheet();bindSections(section,'sec','security')}}

window.addEventListener('hashchange',()=>{const deep=/^#(?:features|learn|faq)\/[a-z0-9-]+$/.test(location.hash);render();if(!deep){window.scrollTo(0,0);focusPageHeading()}});setupMenu();setFooterYear();setupBackToTop();render();connectFirebase();
